import type { MoneyAction, MoneyMetrics } from '@ss/diagram-engine';
import type { CatalogEntry, DiagramLesson } from '@ss/lesson-engine';
import catalogJson from './catalog.json';

type MoneyLesson = DiagramLesson<MoneyMetrics, MoneyAction>;

/** Generated by `pnpm lessons`; validated in CI. */
export const catalog = catalogJson as CatalogEntry[];

const loaders = import.meta.glob<{ default: MoneyLesson }>([
  './*.ts',
  '!./index.ts',
  '!./chapters.ts',
]);

export function loadLesson(slug: string): Promise<MoneyLesson> | null {
  const load = loaders[`./${slug}.ts`];
  return load ? load().then((m) => m.default) : null;
}
